import{_ as t,o as a,c as o,ai as n}from"./chunks/framework.Cg3BiOJh.js";const h=JSON.parse('{"title":"Guide","description":"","frontmatter":{"title":"Guide"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786775408000}'),s={name:"guide/index.md"};function i(c,e,r,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h2 id="start-a-conversation" tabindex="-1">Start a conversation <a class="header-anchor" href="#start-a-conversation" aria-label="Permalink to &quot;Start a conversation&quot;">​</a></h2><p>Put a VPP command on line 1 and the request body on later lines:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!&lt;g&gt;</span></span>
<span class="line"><span>Design a resilient queue.</span></span></code></pre></div><p>The skill prepares the turn through the deterministic runtime, asks the model for body-only content, formats it, validates it, and carries the returned state to the next exchange.</p><h2 id="tags-and-content-contracts" tabindex="-1">Tags and content contracts <a class="header-anchor" href="#tags-and-content-contracts" aria-label="Permalink to &quot;Tags and content contracts&quot;">​</a></h2><ul><li><code>&lt;g&gt;</code> stays conceptual and avoids complete modules or files.</li><li><code>&lt;q&gt;</code> asks broad uncertainty-reducing questions or frames a diagnosis.</li><li><code>&lt;o&gt;</code> realizes a deliverable and includes assumptions, citations, and tests when relevant.</li><li><code>&lt;c&gt;</code> critiques or clarifies concrete deltas, with at most 25 questions.</li><li><code>&lt;o_f&gt;</code> produces the publishable final result and closes the current pipeline.</li><li><code>!&lt;e&gt; --&lt;tag&gt;</code> moves to a new locus; <code>!&lt;e_o&gt;</code> starts an immediate <code>&lt;o&gt;</code> pipeline.</li></ul><p>The runtime enforces tag selection and wrapper structure. It cannot prove semantic quality, citation relevance, or whether a conceptual answer accidentally became a full implementation.</p><h2 id="counters-cycles-and-loci" tabindex="-1">Counters, cycles, and loci <a class="header-anchor" href="#counters-cycles-and-loci" aria-label="Permalink to &quot;Counters, cycles, and loci&quot;">​</a></h2><p>Tag indexes are global to one conversation. If <code>&lt;g_1&gt;</code> is followed by a locus jump that also produces <code>&lt;g&gt;</code>, the next footer says <code>Tag=g_2</code>. A new conversation starts every counter at zero.</p><p>Cycle begins at 1. Every valid user <code>!&lt;c&gt;</code> advances it, capped at 3. A new-locus escape, immediate-output escape, explicit pipeline, or new command after <code>&lt;o_f&gt;</code> resets cycle to 1 but preserves tag counts. Cycle-3 formatting automatically adds both canonical escape choices when they are absent.</p><p>The default locus is <code>default</code>. An unnamed jump becomes <code>locus-2</code>, then <code>locus-3</code>, and so on. Applications can supply a safe explicit name with <code>next_locus</code>.</p><h2 id="modifiers-and-recovery" tabindex="-1">Modifiers and recovery <a class="header-anchor" href="#modifiers-and-recovery" aria-label="Permalink to &quot;Modifiers and recovery&quot;">​</a></h2><p>Supported ordinary modifiers are <code>--correct</code>, <code>--incorrect</code>, <code>--minor</code>, and <code>--major</code>. Pipeline destinations are limited to assistant tags and use angle brackets. Duplicate modifiers, contradictory pairs, and invalid destinations deterministically produce <code>&lt;c&gt;</code> recovery; the host does not call the model for that body.</p><h2 id="implementation-options" tabindex="-1">Implementation options <a class="header-anchor" href="#implementation-options" aria-label="Permalink to &quot;Implementation options&quot;">​</a></h2><p>Use remote MCP when the host supports it. Otherwise use the JSON/OpenAPI operations or the provider-neutral adapter. The bundled offline script exposes the same four operations. Custom instructions are available only as a reduced-assurance fallback.</p><p>See the <a href="/spec/">normative v1.5 specification</a> and the repository <a href="https://github.com/cbassuarez/viable-prompt-protocol/tree/main/docs/adoption" target="_blank" rel="noreferrer">adoption recipes</a>.</p>`,16)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
